using Challenge;void C(string id,Func<bool> f){try{Console.WriteLine($"{id}|{(f()?"pass":"fail")}");}catch{Console.WriteLine($"{id}|fail");}}CatalogRepository R()=>new([new("a","A"),new("b","B"),new("c","C")],new(){{"a",1},{"b",2}});C("C01",()=>new CatalogService(R()).List(0,3).Select(x=>x.Stock).SequenceEqual([1,2,0]));C("C02",()=>{var r=R();new CatalogService(r).List(0,3);return r.QueryCount<=2;});C("C03",()=>new CatalogService(R()).List(1,1).Single().Id=="b");C("C04",()=>new CatalogService(R()).List(2,1).Single().Stock==0);C("C05",()=>{var r=R();var s=new CatalogService(r);s.List(0,1);r.Set("a",9);return s.List(0,1).Single().Stock==9;});
